(function () {
  'use strict';
  const M = window.LocalQuoteModel;
  const storageKey = 'localquote-prototype-v1';
  const app = document.getElementById('app');
  const modal = document.getElementById('modal');
  const modalContent = document.getElementById('modal-content');
  let state, startupNotice = '';
  try { const raw=localStorage.getItem(storageKey);state=raw ? M.decode(raw) : M.seed(); }
  catch {state=M.seed();startupNotice='Saved demo data was unavailable. A fresh sample workspace is ready.';}
  let selectedJobId=state.jobs[0]?.id, activeProviderId=state.providers[0]?.id, proTab='jobs', sortOrder='price';
  let draft={}, postStep=0, photoLoading=false, toastTimer;
  const esc = value => String(value ?? '').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const money = amount => new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:amount%1 ? 2:0}).format(amount);
  const date = value => new Date(value).toLocaleDateString('en-CA',{month:'short',day:'numeric',timeZone:'America/Toronto'});
  const icons={
    Plumbing:'<path d="M6 4v5a3 3 0 0 0 3 3h6v7M4 4h4M13 19h4M12 7h5a3 3 0 0 1 3 3v2M12 5v4M18 12h4"/>',
    Electrical:'<path d="m13 2-8 12h6l-1 8 9-13h-6l0-7Z"/>',
    Handyman:'<path d="m14 5-3 3 5 5 3-3M11 8 3 16a3 3 0 0 0 4 4l9-7M14 5a6 6 0 0 1 7 7M5 17l2 2"/>',
    Landscaping:'<path d="M12 21v-9M12 14C4 14 3 8 4 3c6 0 10 3 8 11ZM12 17c6 0 9-4 8-9-5 0-9 3-8 9Z"/>',
    Cleaning:'<path d="m14 3-6 9M7 11l7 5-4 6-8-5 5-6ZM16 10h6M19 7v6M4 3v4M2 5h4"/>',
    location:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>'
  };
  const icon = (name,cls='') => '<svg class="'+cls+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[name] || icons.Handyman)+'</svg>';
  const pill = (label,cls='') => '<span class="pill '+cls+'">'+esc(label)+'</span>';
  const sampleBadge = job => job.sample ? pill('Sample job','grey') : pill('Your demo job','purple');
  const statusLabel = job => ({open:'Accepting quotes',selected:'Provider selected',completed:'Demo completed'}[job.status]);
  const statusPill = job => pill(statusLabel(job),job.status==='open'?'orange':'green');
  const provider = id => state.providers.find(p=>p.id===id);
  const options = (values,current,placeholder) => (placeholder ? '<option value="">'+esc(placeholder)+'</option>' : '')+values.map(v=>'<option value="'+esc(v)+'" '+(v===current?'selected':'')+'>'+esc(v)+'</option>').join('');
  function notify(message) { const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4200); }
  function commit(mutation) {
    const next=M.clone(state);const result=mutation(next);
    try {localStorage.setItem(storageKey,JSON.stringify(next));}
    catch {throw new Error('Your browser could not save this change. Free some browser storage or remove photos and try again.');}
    state=next;return result;
  }
  function error(message) { const target=document.getElementById('form-error');if(target){target.textContent=message;target.scrollIntoView({block:'nearest'});}else notify(message); }
  function closeModal() {modal.close();modalContent.innerHTML='';photoLoading=false;}
  function openModal(title,body,extra='') {
    modalContent.innerHTML='<div class="modal-header"><h2 id="modal-title">'+esc(title)+'</h2><button class="modal-close" data-action="close" aria-label="Close dialog">×</button></div>'+extra+'<div class="modal-body">'+body+'</div>';
    if(!modal.open)modal.showModal();
  }
  function navigate(route) { if(location.hash==='#'+route){render();}else location.hash=route; }
  function route() {return ['home','jobs','professionals','pilot'].includes(location.hash.slice(1))?location.hash.slice(1):'home';}
  function render() {
    const current=route();
    document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===current);if(a.dataset.nav===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    document.getElementById('nav-count').textContent=state.jobs.length;
    if(current==='home')renderHome();
    if(current==='jobs')renderJobs();
    if(current==='professionals')renderProfessionals();
    if(current==='pilot')renderPilot();
  }
  const houseArt = '<svg class="house-illustration" viewBox="0 0 500 350" fill="none" aria-hidden="true"><circle cx="373" cy="76" r="31" fill="#d4e690"/><path d="M34 271h429" stroke="#becbb0"/><path d="m91 160 108-87 106 87" fill="#9faf8d"/><path d="m305 160 47-38 64 51v98H305V160Z" fill="#c3ceae"/><path d="M109 153h180v118H109V153Z" fill="#f8faee"/><path d="m100 156 99-79 99 79" stroke="#536e4b" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/><path d="M178 217h42v54h-42v-54Z" fill="#5e7853"/><path d="M190 233v20" stroke="#d7e894" stroke-width="2"/><path d="M137 177h29v33h-29zM230 177h29v33h-29z" fill="#c1d6ca" stroke="#7e9a82" stroke-width="2"/><path d="M151 177v33m-14-17h29m78-16v33m-14-17h29" stroke="#7e9a82" stroke-width="2"/><path d="M256 115V88h18v42" fill="#68825b"/><path d="M130 246h23v25h-23z" fill="#bd8560"/><path d="M142 245v-27m0 13c-13 0-16-10-14-15 12-1 16 6 14 15Zm0 7c13 0 16-10 14-15-12-1-16 6-14 15Z" fill="#7f9a62"/><path d="M348 237v34" stroke="#7a8e5b" stroke-width="4"/><ellipse cx="348" cy="208" rx="29" ry="44" fill="#78915f"/><path d="M411 245v26" stroke="#7a8e5b" stroke-width="3"/><ellipse cx="411" cy="230" rx="20" ry="27" fill="#a3b778"/><path d="M70 259v13m-10-13h20" stroke="#7b9163" stroke-width="2"/><path d="M42 105c9-7 15-7 22 0m9 2c8-6 13-6 19 0" stroke="#9cae89" stroke-width="2" stroke-linecap="round"/></svg>';
  function renderHome() {
    app.innerHTML='<div class="container"><section class="hero"><div><div class="eyebrow"><span class="tiny-line"></span> Your neighbourhood. Your next fix.</div><h1>A good home starts<br>with a <em>good pro.</em></h1><p class="subtext">Tell us what needs doing. Compare clear quotes from local professionals. Choose the right fit for your home.</p><div class="hero-buttons"><button class="button dark" data-action="post">Post your first job <span aria-hidden="true">↗</span></button><a class="text-button" href="#professionals">I’m a professional</a></div><div class="hero-note"><span>'+icon('check','icon-inline')+' Job-specific quotes</span><span>'+icon('location','icon-inline')+' Starting in Brampton</span></div></div><div class="hero-art"><div class="art-grid"></div>'+houseArt+'<span class="art-label">Close to home, in Brampton</span><div class="floating-job"><div class="job-mini-icon">'+icon('Plumbing')+'</div><div><h3>Kitchen tap needs a fix</h3><p>Bramalea · This week · Sample job</p></div><span class="tiny-pill">3 quotes</span></div><div class="floating-quote"><span class="avatar">CP</span><div><small>Illustrative quote</small><strong>Cedar Plumbing</strong><small>Labour + standard parts + tax</small></div><span class="quote-amount">$185</span></div></div></section><section class="category-section"><div class="section-heading"><h2>What needs doing?</h2><p>Big or small, start with the job.</p></div><div class="category-grid">'+M.categories.map(c=>'<button class="category-card" data-action="post" data-category="'+c+'"><div class="category-icon">'+icon(c)+'</div><strong>'+c+'</strong><span>'+({Plumbing:'Leaks & fixtures',Electrical:'Lights & outlets',Handyman:'Repairs & assembly',Landscaping:'Yards & gardens',Cleaning:'A fresh start'}[c])+' <b aria-hidden="true">↗</b></span></button>').join('')+'</div></section><section class="how-section"><div><div class="eyebrow">A clearer way to hire</div><h2>One job.<br>A few good options.</h2></div><div class="how-steps"><div class="how-step"><div class="step-num">01</div><h3>Describe the job</h3><p>Add the details, photos, your area, and when you need a hand.</p></div><div class="how-step"><div class="step-num">02</div><h3>Compare the quotes</h3><p>See the price, scope, and availability together. Know what’s included.</p></div><div class="how-step"><div class="step-num">03</div><h3>Choose your pro</h3><p>Find the right fit. In a real pilot, confirm the final scope directly.</p></div></div></section><section class="sample-section"><div class="section-heading"><h2>A look at the neighbourhood.</h2><a class="text-button" href="#jobs">Explore sample jobs ↗</a></div><div class="sample-grid">'+state.jobs.filter(j=>j.sample).slice(0,2).map(homeJobCard).join('')+'</div><p class="compact-note">These jobs, businesses, prices, and profile details are fictional examples. No provider has been verified.</p></section><section class="bottom-cta"><div><h2>You do good work.<br>Let local people find you.</h2><p>Explore matched jobs and send a quote in the professional demo.</p></div><a class="button dark" href="#professionals">For professionals <span aria-hidden="true">↗</span></a></section></div>';
  }
  function homeJobCard(job) {return '<article class="sample-card"><div class="card-top">'+pill(job.category)+sampleBadge(job)+'</div><h3>'+esc(job.title)+'</h3><div class="job-meta"><span>'+icon('location')+esc(job.area)+'</span><span>'+icon('clock')+esc(job.timing)+'</span></div><p class="subtext" style="font-size:12px">'+esc(job.description.slice(0,105))+'…</p><div class="job-bottom"><div style="display:flex;align-items:center"><div class="avatar-stack">'+job.quotes.slice(0,3).map(q=>'<span class="avatar">'+esc(provider(q.providerId)?.initials)+'</span>').join('')+'</div><span class="sample-label">'+job.quotes.length+' quotes</span></div><button class="text-button" data-action="view-job" data-id="'+esc(job.id)+'">View job ↗</button></div></article>';}
  function renderJobs() {
    const s=M.summary(state);
    const selected=state.jobs.find(j=>j.id===selectedJobId) || state.jobs[0];selectedJobId=selected?.id;
    app.innerHTML='<div class="container"><div class="page-heading"><div><div class="eyebrow"><span class="tiny-line"></span> Your home, in good hands</div><h1>My jobs.</h1><p class="subtext">Your requests, quotes, and choices in one place. This workspace includes two sample jobs so you can try the full flow.</p></div><button class="button dark" data-action="post">Post a new job ↗</button></div><div class="stats"><div class="stat"><strong>'+s.open+'</strong><span>Jobs accepting quotes</span></div><div class="stat"><strong>'+s.quotes+'</strong><span>Quotes in this demo</span></div><div class="stat"><strong>'+s.completed+'</strong><span>Demo jobs completed</span></div></div><div class="workspace"><aside class="job-sidebar" aria-label="Choose a job"><div class="sidebar-title">Your jobs <span>'+state.jobs.length+'</span></div>'+state.jobs.map(j=>'<button class="job-tab '+(selected?.id===j.id?'active':'')+'" data-action="select-job" data-id="'+esc(j.id)+'" '+(selected?.id===j.id?'aria-pressed="true"':'aria-pressed="false"')+'>'+pill(j.category)+'<h3>'+esc(j.title)+'</h3><p>'+esc(j.area)+' · '+date(j.createdAt)+'</p><div class="job-tab-foot"><span>'+statusLabel(j)+'</span><span>'+j.quotes.length+' quotes</span></div></button>').join('')+'</aside><section class="job-detail">'+(selected?jobDetail(selected):'<div class="empty"><h3>Start with your first job.</h3><p>Describe the work to try the quote workflow.</p><button class="button dark" data-action="post">Post a job</button></div>')+'</section></div></div>';
  }
  function jobDetail(job) {
    let banner='';
    if(job.status!=='open'){
      const q=job.quotes.find(q=>q.id===job.selectedQuoteId), p=provider(q?.providerId);
      banner='<div class="status-banner"><strong>'+ (job.status==='completed'?'Demo job marked complete':'You selected '+esc(p?.company))+'</strong>'+money(q?.amount || 0)+' total quote · '+esc(q?.availability)+'. This is a demo selection; no provider has been contacted.<div>'+(job.status==='selected'?'<button class="button dark small" data-action="complete" data-id="'+esc(job.id)+'">Mark demo job complete</button> ':'')+'<button class="button outline small" data-action="reopen" data-id="'+esc(job.id)+'">Reopen demo job</button></div></div>';
    }
    const photos=(job.photos || []).filter(src=>/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(src));
    return '<div class="card-top">'+pill(job.category)+sampleBadge(job)+'</div><h2>'+esc(job.title)+'</h2><div class="job-meta"><span>'+icon('location')+esc(job.area)+'</span><span>'+icon('clock')+'Posted '+date(job.createdAt)+'</span></div><p class="job-description">'+esc(job.description)+'</p>'+(photos.length?'<div class="job-photos">'+photos.map((src,i)=>'<a href="'+esc(src)+'" target="_blank" rel="noopener" aria-label="Open job photo '+(i+1)+'"><img src="'+esc(src)+'" alt="Photo '+(i+1)+' supplied for this job"></a>').join('')+'</div>':'')+'<div class="detail-grid"><div><small>Timing</small>'+esc(job.timing)+'</div><div><small>Budget</small>'+esc(job.budget)+'</div><div><small>Status</small>'+esc(statusLabel(job))+'</div></div>'+banner+'<div class="quote-heading"><h3>'+job.quotes.length+' '+(job.quotes.length===1?'quote':'quotes')+'</h3>'+(job.quotes.length?'<label><span class="skip">Sort quotes</span><select id="quote-sort" aria-label="Sort quotes"><option value="price" '+(sortOrder==='price'?'selected':'')+'>Lowest price</option><option value="availability" '+(sortOrder==='availability'?'selected':'')+'>Earliest availability</option><option value="recent" '+(sortOrder==='recent'?'selected':'')+'>Newest quote</option></select></label>':'')+'</div>'+(job.quotes.length>1?'<button class="button soft small" data-action="compare" data-id="'+esc(job.id)+'">Compare quotes side by side ↗</button>':'')+M.sortedQuotes(job,sortOrder).map(q=>quoteCard(job,q)).join('')+(!job.quotes.length?'<div class="empty"><h3>Your request is ready.</h3><p>To test a quote, switch to the provider view and respond to this job. No real professionals are notified.</p><button class="button dark small" data-action="provider-for-job" data-id="'+esc(job.id)+'">Try the provider view ↗</button></div>':'')+'<div class="note">All quote amounts are in CAD. Compare inclusions and exclusions before choosing. Profiles and credentials shown here are unverified demo data.</div>';
  }
  function quoteCard(job,q) {
    const p=provider(q.providerId),chosen=job.selectedQuoteId===q.id;
    return '<article class="quote-card '+(chosen?'selected':'')+'"><div class="quote-card-top"><span class="avatar">'+esc(p?.initials)+'</span><div><div class="provider-name">'+esc(p?.company)+'</div><div class="provider-sub">'+esc(p?.category)+' · '+esc(p?.years)+' years '+(p?.sample?'(sample)':'stated')+'</div></div><div class="quote-price"><strong>'+money(q.amount)+'</strong><small>Total quote · CAD</small></div></div><div class="quote-tags">'+pill(q.availability)+pill(p?.sample?'Sample profile':'Review pending','grey')+(chosen?pill('Your selection','green'):'')+'</div><p>'+esc(q.scope)+'</p><div class="quote-actions"><button class="text-button" data-action="profile" data-id="'+esc(q.providerId)+'">View profile</button>'+(job.status==='open'?'<button class="button dark small" data-action="choose" data-id="'+esc(job.id)+'" data-quote="'+esc(q.id)+'">Choose this quote ↗</button>':'<span>'+ (chosen?'Selected for this demo':'Other quote')+'</span>')+'</div></article>';
  }
  function renderProfessionals() {
    const p=provider(activeProviderId) || state.providers[0];activeProviderId=p?.id;
    app.innerHTML='<div class="container"><div class="page-heading"><div><div class="eyebrow"><span class="tiny-line"></span> Good work starts here</div><h1>Local jobs. Clear scope.</h1><p class="subtext">Explore the professional workflow. Choose a demo profile, find matching jobs, and send a quote with your price and availability.</p></div><button class="button dark" data-action="join">Create a demo profile ↗</button></div><div class="toolbar"><div class="segmented" aria-label="Professional view"><button data-action="pro-tab" data-tab="jobs" class="'+(proTab==='jobs'?'active':'')+'" aria-pressed="'+(proTab==='jobs')+'">Matched jobs</button><button data-action="pro-tab" data-tab="profile" class="'+(proTab==='profile'?'active':'')+'" aria-pressed="'+(proTab==='profile')+'">My profile</button></div><select id="provider-select" aria-label="Choose demo provider profile">'+state.providers.map(x=>'<option value="'+esc(x.id)+'" '+(x.id===activeProviderId?'selected':'')+'>'+esc(x.company)+' · '+esc(x.category)+'</option>').join('')+'</select></div>'+(proTab==='jobs'?proJobs(p):proProfile(p))+'</div>';
  }
  function proJobs(p) {
    const jobs=M.matchedJobs(state,p.id);
    return '<div class="note" style="margin:0 0 22px">Viewing as '+esc(p.company)+' · '+esc(p.category)+'. '+(p.sample?'This is a fictional sample provider.':'This demo profile is pending review.')+' Only open '+esc(p.category.toLowerCase())+' jobs are shown.</div><div class="pro-grid">'+jobs.map(j=>{
      const quoted=j.quotes.find(q=>q.providerId===p.id);
      return '<article class="open-job"><div class="card-top">'+pill(j.category)+sampleBadge(j)+'</div><h3>'+esc(j.title)+'</h3><div class="job-meta"><span>'+icon('location')+esc(j.area)+'</span><span>'+icon('clock')+esc(j.timing)+'</span></div><p>'+esc(j.description)+'</p><div class="open-job-bottom"><span>Budget: '+esc(j.budget)+'<br>'+j.quotes.length+' quotes so far</span>'+(quoted?pill('You quoted '+money(quoted.amount),'green'):'<button class="button dark small" data-action="quote" data-id="'+esc(j.id)+'">Send a quote ↗</button>')+'</div></article>';
    }).join('')+'</div>'+(!jobs.length?'<div class="empty" style="margin-bottom:40px"><h3>No matching open jobs yet.</h3><p>Try posting a '+esc(p.category.toLowerCase())+' job as a customer, then return to this profile to quote on it.</p><button class="button dark" data-action="post" data-category="'+esc(p.category)+'">Post a demo job</button></div>':'')+'<div class="bottom-cta"><div><h2>Start with the work you do best.</h2><p>Create your own local demo profile and try the professional flow.</p></div><button class="button dark" data-action="join">Create a demo profile ↗</button></div>';
  }
  function proProfile(p) {
    return '<div class="profile-layout"><article class="profile-card"><div class="profile-heading"><span class="avatar">'+esc(p.initials)+'</span><div><h3>'+esc(p.company)+'</h3><div class="provider-sub">'+esc(p.category)+' · '+esc(p.area)+'</div></div></div><p class="provider-bio">'+esc(p.bio)+'</p>'+pill(p.sample?'Fictional sample profile':'Credential review pending',p.sample?'grey':'orange')+'<ul><li>Experience: '+p.years+' years '+(p.sample?'(sample)':'self-reported')+'</li><li>Trade credentials: '+esc(p.credential)+'</li><li>Insurance: '+esc(p.insurance)+'</li></ul><div class="note warning">This is not a verified provider listing. Before a real pilot introduction, the operator must review the relevant credentials and evidence.</div></article><article class="onboard-card"><h3>What a clear quote should cover</h3><ul class="pilot-list"><li><strong>The complete price</strong>State labour, materials, applicable taxes, and any limits or conditions.</li><li><strong>Exactly what is included</strong>Describe the work, cleanup, and parts you are supplying.</li><li><strong>What needs a separate agreement</strong>Explain exclusions and when the quote may need to change.</li><li><strong>When you can do it</strong>Give a realistic availability window, then confirm a date directly in a real pilot.</li></ul><div class="note">The prototype stores data in this browser. Creating a profile does not create an account, send an email, or publish a business listing.</div></article></div>';
  }
  function renderPilot() {
    const done=M.pilotTasks.filter(t=>state.pilot[t.id]).length;
    app.innerHTML='<div class="container"><div class="page-heading"><div><div class="eyebrow"><span class="tiny-line"></span> From a working idea to real jobs</div><h1>The Brampton pilot.</h1><p class="subtext">Use this MVP to learn whether customers get useful quotes and professionals get worthwhile jobs. These are proposed targets, not results.</p></div>'+pill(done+' / '+M.pilotTasks.length+' steps done','green')+'</div><div class="metric-grid"><div class="metric"><strong>1 area</strong><span>Brampton first</span></div><div class="metric"><strong>10 people</strong><span>Customer interview target</span></div><div class="metric"><strong>5 pros</strong><span>Provider recruitment target</span></div><div class="metric"><strong>5 jobs</strong><span>First pilot request target</span></div></div><div class="pilot-layout"><section class="pilot-panel"><h3>Make the first matches happen.</h3><p>A small manual pilot lets you learn which parts need software. Tick a step when you have actually completed it.</p>'+M.pilotTasks.map(t=>'<label class="pilot-task '+(state.pilot[t.id]?'done':'')+'"><input type="checkbox" data-pilot="'+t.id+'" '+(state.pilot[t.id]?'checked':'')+'><span><strong>'+esc(t.title)+'</strong><small>'+esc(t.detail)+'</small></span></label>').join('')+'</section><div><section class="pilot-panel"><h3>What we are testing</h3><ul class="pilot-list"><li><strong>Customer problem</strong>Does getting a clear repair quote take too much effort or create uncertainty?</li><li><strong>Provider problem</strong>Can a well-described, nearby job be a useful lead?</li><li><strong>Product hypothesis</strong>Photos plus comparable price, scope, and availability make choosing easier.</li><li><strong>First category hypothesis</strong>Start the live pilot with small plumbing repairs. Keep the five-category prototype available for testing.</li><li><strong>Useful evidence</strong>Count requests that receive a suitable quote, time to first quote, selections, completed jobs, and repeat interest.</li></ul></section><section class="pilot-panel" style="margin-top:20px"><h3>Interview questions</h3><ul class="pilot-list"><li>“Tell me about the last time you hired someone for a home repair.”</li><li>“How did you find them, and what was difficult?”</li><li>“What made you trust the quote?”</li><li>For providers: “Tell me about the last job lead that wasted your time.”</li></ul><p style="margin:15px 0 0;font-size:11px">Ask about real experiences and look for repeated problems. A compliment about the idea is not the same as a job request.</p><div class="source-links">Background reading: <a href="https://www.ycombinator.com/library/Ri-how-to-pick-a-startup-idea" target="_blank" rel="noopener">YC: talking to customers ↗</a><a href="https://www.taskrabbit.ca/how-it-works-canada" target="_blank" rel="noopener">Taskrabbit’s current flow ↗</a></div></section></div></div><div class="prototype-tools"><span>Prototype data and checklist are stored only in this browser.</span><div><button class="text-button" data-action="export">Export demo data</button><button class="text-button" data-action="reset">Reset prototype</button></div></div></div>';
  }
  function startPost(category) {draft={category:category || '',title:'',description:'',area:'',timing:'',budget:'',photos:[]};postStep=0;showPost();}
  function collectDraft() {for(const key of ['title','description','area','timing','budget']){const el=document.getElementById('job-'+key);if(el)draft[key]=el.value;}}
  function showPost() {
    let body='';
    if(postStep===0){body='<p class="subtext" style="font-size:12px;margin-bottom:18px">Start with what needs doing. Your request stays in this private demo.</p><label style="font-size:12px;font-weight:600">Service category</label><div class="form-category-grid">'+M.categories.map(c=>'<button class="form-category '+(draft.category===c?'chosen':'')+'" data-action="category" data-category="'+c+'" aria-pressed="'+(draft.category===c)+'">'+icon(c)+c+'</button>').join('')+'</div><div class="field"><label for="job-title">A short title</label><input id="job-title" maxlength="100" minlength="8" value="'+esc(draft.title)+'" placeholder="e.g. Fix a leaking kitchen tap" required></div><div class="field"><label for="job-description">Tell the professional about the job</label><textarea id="job-description" maxlength="2000" minlength="25" placeholder="What needs fixing? What should the quote include?" required>'+esc(draft.description)+'</textarea><small>At least 25 characters. Mention any parts you already have.</small></div><div class="field"><label for="job-photos">Photos (optional)</label><input id="job-photos" type="file" accept="image/jpeg,image/png,image/webp" multiple><small>Up to 2 JPG, PNG, or WebP photos · 1 MB per photo in this demo.</small><div class="photo-previews">'+draft.photos.map((p,i)=>'<img src="'+esc(p)+'" alt="Attached job photo '+(i+1)+'">').join('')+'</div>'+(draft.photos.length?'<button class="text-button" style="margin-top:8px" data-action="remove-photos">Remove photos</button>':'')+'</div>';}
    if(postStep===1){body='<p class="subtext" style="font-size:12px;margin-bottom:22px">Give providers enough context to send a useful quote. An area is enough for this prototype.</p><div class="field"><label for="job-area">Where in Brampton?</label><select id="job-area" required>'+options(M.areas,draft.area,'Choose your area')+'</select></div><div class="row-fields"><div class="field"><label for="job-timing">When do you need it?</label><select id="job-timing" required>'+options(M.timings,draft.timing,'Choose timing')+'</select></div><div class="field"><label for="job-budget">Budget range</label><select id="job-budget" required>'+options(M.budgets,draft.budget,'Choose a range')+'</select></div></div><div class="note">This demo does not ask for your full address or send your details to anyone.</div>';}
    if(postStep===2){body='<h3>'+esc(draft.title)+'</h3><div style="margin-top:12px">'+pill(draft.category)+'</div><div class="review-label">Job details</div><p class="review-value">'+esc(draft.description)+'</p><div class="review-grid"><div><div class="review-label">Area</div><div class="review-value">'+esc(draft.area)+'</div></div><div><div class="review-label">When</div><div class="review-value">'+esc(draft.timing)+'</div></div><div><div class="review-label">Budget</div><div class="review-value">'+esc(draft.budget)+'</div></div><div><div class="review-label">Photos</div><div class="review-value">'+draft.photos.length+' attached</div></div></div><div class="note">Posting creates a job in this browser’s demo workspace. It does not notify real providers or publish your request.</div>';}
    body+='<div id="form-error" class="error" role="alert"></div><div class="modal-footer">'+(postStep?'<button class="button outline" data-action="post-back">Back</button>':'<span>Step 1 of 3</span>')+'<button class="button dark" id="post-next" data-action="'+(postStep===2?'post-submit':'post-next')+'" '+(photoLoading?'disabled':'')+'>'+(postStep===2?'Post demo job ↗':'Continue →')+'</button></div>';
    openModal(['Describe your job','Location & timing','Review your request'][postStep],body,'<div class="progress-line" aria-label="Step '+(postStep+1)+' of 3">'+[0,1,2].map(i=>'<span class="'+(i<=postStep?'on':'')+'"></span>').join('')+'</div>');
  }
  function nextPost() {collectDraft();if(photoLoading)return;if(postStep===0){if(!M.categories.includes(draft.category))return error('Choose a service category.');if(draft.title.trim().length<8)return error('Use a title of at least 8 characters.');if(draft.description.trim().length<25)return error('Add a description of at least 25 characters.');}if(postStep===1){try{M.validateJob(draft);}catch(e){return error(e.message);}}postStep++;showPost();}
  async function readPhotos(files) {
    if(files.length>2)throw new Error('Attach no more than two photos.');
    for(const f of files){if(!['image/jpeg','image/png','image/webp'].includes(f.type))throw new Error('Use JPG, PNG, or WebP photos.');if(f.size>1024*1024)throw new Error('Each photo must be 1 MB or smaller in this demo.');}
    return Promise.all(files.map(f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('A photo could not be read. Try another file.'));r.readAsDataURL(f);})));
  }
  function profileModal(id) {
    const p=M.getProvider(state,id);
    openModal(p.company,'<div class="profile-heading"><span class="avatar">'+esc(p.initials)+'</span><div><h3>'+esc(p.category)+'</h3><span class="provider-sub">'+esc(p.area)+' · '+p.years+' years '+(p.sample?'(sample)':'self-reported')+'</span></div></div><p class="provider-bio">'+esc(p.bio)+'</p><div class="review-label">Trade credentials</div><p class="review-value">'+esc(p.credential)+'</p><div class="review-label">Insurance</div><p class="review-value">'+esc(p.insurance)+'</p><div class="note warning">'+(p.sample?'This provider and all profile details are fictional sample data.':'This profile is pending review; details are self-reported.')+' No credentials, identity, or insurance have been verified.</div><div class="modal-footer"><span>Professional profile preview</span><button class="button dark" data-action="close">Done</button></div>');
  }
  function compareModal(jobId) {
    const job=M.getJob(state,jobId),quotes=M.sortedQuotes(job,sortOrder);
    const rows=[['Total (CAD)',q=>money(q.amount)],['Availability',q=>esc(q.availability)],['Experience',q=>esc(provider(q.providerId)?.years)+' years '+(provider(q.providerId)?.sample?'(sample)':'stated')],['Profile status',q=>provider(q.providerId)?.sample?'Fictional sample':'Review pending'],['Scope & conditions',q=>esc(q.scope)]];
    openModal('Compare quotes','<p style="font-size:13px">'+esc(job.title)+'</p><div class="comparison-scroll"><table class="compare-table"><thead><tr><th scope="col">Details</th>'+quotes.map(q=>'<th scope="col">'+esc(provider(q.providerId)?.company)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(([label,fn])=>'<tr><th scope="row" style="font-size:10px;color:var(--muted)">'+label+'</th>'+quotes.map(q=>'<td>'+fn(q)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="note">These are demo quotes. Price alone does not establish suitability. Check scope, conditions, and credentials before a real job.</div><div class="modal-footer"><span>Choose a quote from the job page.</span><button class="button dark" data-action="close">Back to job</button></div>');
  }
  function chooseModal(jobId,quoteId) {
    const job=M.getJob(state,jobId),q=job.quotes.find(q=>q.id===quoteId),p=provider(q?.providerId);if(!q)return;
    openModal('Choose this provider?','<h3>'+esc(p.company)+'</h3><p class="provider-bio">'+esc(job.title)+'</p><div class="detail-grid"><div><small>Total quote</small>'+money(q.amount)+' CAD</div><div><small>Availability</small>'+esc(q.availability)+'</div><div><small>Profile</small>'+esc(p.sample?'Sample':'Review pending')+'</div></div><p class="review-value">'+esc(q.scope)+'</p><div class="note">This records your choice in the demo. No booking, message, payment, or provider contact is created.</div><div id="form-error" class="error" role="alert"></div><div class="modal-footer"><button class="button outline" data-action="close">Back</button><button class="button dark" data-action="confirm-choose" data-id="'+esc(jobId)+'" data-quote="'+esc(quoteId)+'">Confirm demo selection</button></div>');
  }
  function quoteModal(jobId) {
    const job=M.getJob(state,jobId),p=provider(activeProviderId);
    openModal('Quote for this job','<p style="font-size:13px;font-weight:600;margin-bottom:5px">'+esc(job.title)+'</p><p style="font-size:11px;color:var(--muted);margin-bottom:22px">Submitting as '+esc(p.company)+'</p><form id="quote-form" data-job="'+esc(jobId)+'" data-provider="'+esc(p.id)+'"><div class="row-fields"><div class="form-field"><label for="quote-amount">Total quote (CAD)</label><input id="quote-amount" name="amount" type="number" min="0.01" max="100000" step="0.01" placeholder="185.00" required><small>Include applicable tax in the total.</small></div><div class="form-field"><label for="quote-availability">Earliest availability</label><select id="quote-availability" name="availability" required>'+options(M.slots,'','Choose a window')+'</select></div></div><div class="form-field"><label for="quote-scope">Inclusions, exclusions & conditions</label><textarea id="quote-scope" name="scope" minlength="25" maxlength="1500" required placeholder="Labour, parts, cleanup, tax, and anything that would need a new price…"></textarea></div><div class="note">This quote stays in the prototype. The customer view in this browser will show it immediately.</div><div id="form-error" class="error" role="alert"></div><div class="modal-footer"><button type="button" class="button outline" data-action="close">Cancel</button><button class="button dark" type="submit">Send demo quote ↗</button></div></form>');
  }
  function joinModal() {
    openModal('Create your demo profile','<p class="subtext" style="font-size:12px;margin-bottom:22px">Test the provider flow with your own profile. No account is created, and no email is sent. Use example contact details for testing.</p><form id="provider-form"><div class="row-fields"><div class="form-field"><label for="pro-company">Business name</label><input id="pro-company" name="company" minlength="3" maxlength="80" placeholder="Your business" required></div><div class="form-field"><label for="pro-email">Email (demo only)</label><input id="pro-email" name="email" type="email" maxlength="200" placeholder="you@example.com" required></div></div><div class="row-fields"><div class="form-field"><label for="pro-category">Main service</label><select id="pro-category" name="category" required>'+options(M.categories,'','Choose a service')+'</select></div><div class="form-field"><label for="pro-years">Years of experience</label><input id="pro-years" name="years" type="number" min="0" max="60" step="1" value="0" required></div></div><div class="form-field"><label for="pro-area">Main service area</label><select id="pro-area" name="area" required>'+options(M.areas,'','Choose your area')+'</select></div><div class="form-field"><label for="pro-bio">Describe the work you do</label><textarea id="pro-bio" name="bio" minlength="25" maxlength="1000" placeholder="Your main services, experience, and the jobs you take on…" required></textarea></div><div class="row-fields"><div class="form-field"><label for="pro-credential">Trade credential summary</label><input id="pro-credential" name="credential" maxlength="200" placeholder="To be reviewed"><small>Do not upload identity documents here.</small></div><div class="form-field"><label for="pro-insurance">Insurance summary</label><input id="pro-insurance" name="insurance" maxlength="200" placeholder="To be reviewed"></div></div><div class="form-field"><label class="check-label"><input type="checkbox" name="consent" required><span>I understand this is a browser-local demo profile, and no credentials or insurance will be verified by this form.</span></label></div><div id="form-error" class="error" role="alert"></div><div class="modal-footer"><button class="button outline" type="button" data-action="close">Cancel</button><button class="button dark" type="submit">Create demo profile ↗</button></div></form>');
  }
  function aboutModal(){openModal('About this first version','<h3>A marketplace you can try today.</h3><p class="provider-bio">LocalQuote is a working name for a Brampton home-services startup. Customers describe jobs, professionals submit quotes, and customers compare price, scope, and availability.</p><ul class="pilot-list"><li><strong>What works here</strong>Job posting, local photo attachments, provider profiles, category matching, quoting, sorting, comparison, selection, demo completion, and a pilot checklist.</li><li><strong>Where data goes</strong>Everything is saved in this browser. Other people or devices cannot see these jobs. No accounts, provider notifications, payments, or real bookings are connected.</li><li><strong>Sample content</strong>All seeded businesses, experience, credentials, jobs, and prices are fictional. None are endorsements or market price estimates.</li><li><strong>Next real-world step</strong>Recruit a small group of providers and coordinate a few real customer requests manually before opening a public service.</li></ul><div class="modal-footer"><a class="text-button" href="#pilot" data-action="go-pilot">See the pilot plan ↗</a><button class="button dark" data-action="close">Got it</button></div>');}
  document.addEventListener('click',event=>{
    const target=event.target.closest('[data-action]');if(!target)return;
    const a=target.dataset.action,id=target.dataset.id;
    try{
      if(a==='post')startPost(target.dataset.category);
      if(a==='close')closeModal();
      if(a==='category'){collectDraft();draft.category=target.dataset.category;showPost();}
      if(a==='remove-photos'){collectDraft();draft.photos=[];showPost();}
      if(a==='post-next')nextPost();
      if(a==='post-back'){collectDraft();postStep--;showPost();}
      if(a==='post-submit'){if(photoLoading)return;const job=commit(s=>M.addJob(s,draft));selectedJobId=job.id;closeModal();navigate('jobs');notify('Demo job posted. Try sending a quote from the provider view.');}
      if(a==='view-job'){selectedJobId=id;navigate('jobs');}
      if(a==='select-job'){selectedJobId=id;render();}
      if(a==='profile')profileModal(id);
      if(a==='compare')compareModal(id);
      if(a==='choose')chooseModal(id,target.dataset.quote);
      if(a==='confirm-choose'){commit(s=>M.selectQuote(s,id,target.dataset.quote));closeModal();render();notify('Demo provider selected. No real booking was sent.');}
      if(a==='complete'){commit(s=>M.completeJob(s,id));render();notify('Demo job marked complete.');}
      if(a==='reopen'){commit(s=>M.reopenJob(s,id));render();notify('Demo job reopened for quotes.');}
      if(a==='provider-for-job'){const job=M.getJob(state,id);activeProviderId=state.providers.find(p=>p.category===job.category)?.id || activeProviderId;proTab='jobs';navigate('professionals');}
      if(a==='pro-tab'){proTab=target.dataset.tab;render();}
      if(a==='quote')quoteModal(id);
      if(a==='join')joinModal();
      if(a==='about')aboutModal();
      if(a==='go-pilot'){closeModal();navigate('pilot');}
      if(a==='export'){
        const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='localquote-demo-data.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);notify('Demo data exported. It may include locally entered contact details.');
      }
      if(a==='reset')openModal('Reset the prototype?','<p class="provider-bio">This removes jobs, quotes, profiles, photos, and checklist changes you created in this browser, then restores the original sample workspace. Export your data first if you want to keep a copy.</p><div id="form-error" class="error" role="alert"></div><div class="modal-footer"><button class="button outline" data-action="close">Keep my changes</button><button class="button dark" data-action="confirm-reset">Reset demo data</button></div>');
      if(a==='confirm-reset'){const next=M.seed();try{localStorage.setItem(storageKey,JSON.stringify(next));}catch{throw new Error('Your browser could not reset the saved data.');}state=next;selectedJobId=state.jobs[0].id;activeProviderId=state.providers[0].id;closeModal();render();notify('Sample workspace restored.');}
    }catch(e){error(e.message);}
  });
  document.addEventListener('change',async event=>{
    const t=event.target;
    if(t.id==='quote-sort'){sortOrder=t.value;render();}
    if(t.id==='provider-select'){activeProviderId=t.value;render();}
    if(t.dataset.pilot){try{commit(s=>{s.pilot[t.dataset.pilot]=t.checked;});render();}catch(e){notify(e.message);render();}}
    if(t.id==='job-photos'){
      collectDraft();photoLoading=true;const next=document.getElementById('post-next');if(next)next.disabled=true;
      try{const photos=await readPhotos(Array.from(t.files));draft.photos=photos;}catch(e){error(e.message);photoLoading=false;if(next)next.disabled=false;t.value='';return;}
      photoLoading=false;if(modal.open)showPost();
    }
  });
  document.addEventListener('submit',event=>{
    const form=event.target;if(!['quote-form','provider-form'].includes(form.id))return;event.preventDefault();
    const values=Object.fromEntries(new FormData(form).entries());
    try{
      if(form.id==='quote-form'){commit(s=>M.addQuote(s,form.dataset.job,form.dataset.provider,values));selectedJobId=form.dataset.job;closeModal();render();notify('Demo quote submitted. Open My jobs to compare it.');}
      if(form.id==='provider-form'){values.consent=form.elements.consent.checked;const p=commit(s=>M.addProvider(s,values));activeProviderId=p.id;proTab='jobs';closeModal();navigate('professionals');notify('Demo profile created. Credential review is pending.');}
    }catch(e){error(e.message);}
  });
  modal.addEventListener('click',event=>{if(event.target===modal)closeModal();});
  modal.addEventListener('cancel',()=>{photoLoading=false;});
  window.addEventListener('hashchange',()=>{if(modal.open)closeModal();render();window.scrollTo({top:0,behavior:'auto'});app.focus({preventScroll:true});});
  render();if(startupNotice)notify(startupNotice);
})();
